import os
import pandas as pd
import streamlit as st

st.set_page_config(page_title="Stock Market Progression", layout="wide")
st.title("📈 Real-World Stock Market Progression")

CSV_FILE = "market_history.csv"

if not os.path.exists(CSV_FILE):
    st.warning("No market data found yet. Run your GitHub Action workflow first to generate market_history.csv.")
    st.stop()

# Load the CSV generated by your GitHub Action
df = pd.read_csv(CSV_FILE)
df["timestamp_utc"] = pd.to_datetime(df["timestamp_utc"])

# Sidebar filter for tickers
tickers = df["ticker"].unique().tolist()
selected_tickers = st.sidebar.multiselect("Select Tickers", tickers, default=tickers)

filtered_df = df[df["ticker"].isin(selected_tickers)]

# Display latest prices in metric cards
st.subheader("Latest Market Snapshot")
cols = st.columns(len(selected_tickers) if selected_tickers else 1)

for idx, ticker in enumerate(selected_tickers):
    ticker_data = filtered_df[filtered_df["ticker"] == ticker].sort_values("timestamp_utc")
    if not ticker_data.empty:
        latest = ticker_data.iloc[-1]
        cols[idx].metric(
            label=ticker,
            value=f"{latest['price']:,.2f}",
            delta=f"{latest['change_pct']}%"
        )

# Pivot data for an interactive progression line chart
st.subheader("Historical Progression")
chart_data = filtered_df.pivot_table(
    index="timestamp_utc", 
    columns="ticker", 
    values="price"
)
st.line_chart(chart_data)

# Show raw data table
with st.expander("View Raw Logged Data"):
    st.dataframe(filtered_df.sort_values("timestamp_utc", ascending=False), use_container_width=True)
